2	const fs = require('fs');
3	const path = require('path');
4	
5	const SKILLS_DIR = path.join(process.cwd(), '.claude', 'skills');
6	
7	let raw = '';
8	process.stdin.setEncoding('utf8');
9	process.stdin.on('data', c => raw += c);
10	process.stdin.on('end', () => {
11	  const skills = scanSkills();
12	  if (skills.length === 0) { process.exit(0); return; }
13	
14	  const lines = skills.map(s => `- **${s.name}**: ${s.description}`).join('\n');
15	  process.stdout.write(`<startup-index>\n\n### Skills (${skills.length}) — loaded from frontmatter, do NOT re-read SKILL.md files\n\n${lines}\n\n</startup-index>\n`);
16	  process.exit(0);
17	});
18	
19	function parseFrontmatter(content) {
20	  const match = content.match(/^---\s*\n([\s\S]*?)\n---/);
21	  if (!match) return {};
22	  const out = {};
23	  for (const line of match[1].split('\n')) {
24	    const sep = line.indexOf(':');
25	    if (sep === -1) continue;
26	    const k = line.slice(0, sep).trim();
27	    const v = line.slice(sep + 1).trim().replace(/^["']|["']$/g, '');
28	    if (k) out[k] = v;
29	  }
30	  return out;
31	}
32	
33	function scanSkills() {
34	  try {
35	    return fs.readdirSync(SKILLS_DIR, { withFileTypes: true })
36	      .filter(d => d.isDirectory())
37	      .flatMap(d => {
38	        const skillPath = path.join(SKILLS_DIR, d.name, 'SKILL.md');
39	        try {
40	          const fm = parseFrontmatter(fs.readFileSync(skillPath, 'utf8'));
41	          if (!fm.name && !fm.description) return [];
42	          return [{ name: fm.name || d.name, description: fm.description || '' }];
43	        } catch { return []; }
44	      });
45	  } catch { return []; }
46	}
