3	'use strict';
4	const fs = require('fs');
5	const bus = require('./scout-bus.js');
6	
7	const SEV_ORDER = { CRITICAL: 4, HIGH: 3, WARN: 2, INFO: 1 };
8	
9	function emitContext(msg) {
10	  process.stderr.write(JSON.stringify({
11	    hookSpecificOutput: { hookEventName: 'PreToolUse', additionalContext: msg }
12	  }) + '\n');
13	}
14	
15	function severityIcon(sev) {
16	  return { CRITICAL: '🔴', HIGH: '🟠', WARN: '🟡', INFO: '🔵' }[sev] || '⚪';
17	}
18	
19	try {
20	  const b = bus.readBus();
21	  const pending = bus.getUnconsumed(b);
22	
23	  if (pending.length === 0) {
24	    process.exit(0);
25	  }
26	
27	  // Sort: severity desc, then oldest first (most urgent first)
28	  pending.sort((a, b) =>
29	    (SEV_ORDER[b.severity] || 0) - (SEV_ORDER[a.severity] || 0) ||
30	    new Date(a.ts) - new Date(b.ts)
31	  );
32	
33	  // Cap at 3 per injection to avoid flooding context
34	  const toInject = pending.slice(0, 3);
35	
36	  const lines = toInject.map(e => {
37	    const time = new Date(e.ts).toISOString().slice(11, 19);
38	    return `${severityIcon(e.severity)} ${e.scout} [${e.severity}] @${time} — ${e.finding}`;
39	  });
40	
41	  const block = [
42	    `<scout-findings count="${toInject.length}">`,
43	    ...lines,
44	    '</scout-findings>',
45	  ].join('\n');
46	
47	  // Mark consumed and persist
48	  bus.markConsumed(b, toInject.map(e => e.id));
49	  bus.writeBus(b);
50	
51	  emitContext(block);
52	} catch (_) {
53	  // Never block PreToolUse
54	}
55	
56	process.exit(0);
